# -*- coding: utf-8 -*-
class VersionInfo:
    def __init__(self, major, minor, patch, prerelease, build):
        self._major = int(major)
        self._minor = int(minor)
        self._patch = int(patch)
        self._prerelease = str(prerelease)
        self._build = str(build)

    def __iter__(self):
        return iter([self._major, self._minor, self._patch, self._prerelease, self._build])

    def __eq__(self, other):
        if isinstance(other, tuple):
            return self._major == other[0] and self._minor == other[1] and self._patch == other[2] and self._prerelease == other[3] and self._build == other[4]
        else:
            raise TypeError('Unsupport type for comparison')

    def __lt__(self, other):
        if isinstance(other, tuple):
            return (self._major, self._minor, self._patch, self._prerelease, self._build) < other
        else:
            raise TypeError('Unsupport type for comparison')

    def __le__(self, other):
        if isinstance(other, tuple):
            return (self._major, self._minor, self._patch, self._prerelease, self._build) <= other
        else:
            raise TypeError('Unsupport type for comparison')

    def __gt__(self, other):
        if isinstance(other, tuple):
            return (self._major, self._minor, self._patch, self._prerelease, self._build) > other
        else:
            raise TypeError('Unsupport type for comparison')

    def __ge__(self, other):
        if isinstance(other, tuple):
            return (self._major, self._minor, self._patch, self._prerelease, self._build) >= other
        else:
            raise TypeError('Unsupport type for comparison')

    def bump_major(self):
        return VersionInfo(self._major + 1, self._minor, self._patch, self._prerelease, self._build)

    def bump_minor(self):
        return VersionInfo(self._major, self._minor + 1, self._patch, self._prerelease, self._build)

    def bump_patch(self):
        return VersionInfo(self._major, self._minor, self._patch + 1, self._prerelease, self._build)

    def bump_prerelease(self):
        return VersionInfo(self._major, self._minor, self._patch, self._prerelease + 'bump', self._build)

    def bump_build(self):
        return VersionInfo(self._major, self._minor, self._patch, self._prerelease, str(int(self._build) + 1))

    def replace(self, **kwargs):
        new_version = VersionInfo(self._major, self._minor, self._patch, self._prerelease, self._build)
        for key, value in kwargs.items():
            if key in ['major', 'minor', 'patch', 'prerelease', 'build']:
                if key == 'major':
                    new_version = new_version.bump_major()
                elif key == 'minor':
                    new_version = new_version.bump_minor()
                elif key == 'patch':
                    new_version = new_version.bump_patch()
                elif key == 'prerelease':
                    new_version._prerelease = value
                else:
                    new_version._build = value
        return new_version

    @property
    def major(self):
        raise AttributeError('Cannot modify version info')

    @property
    def minor(self):
        raise AttributeError('Cannot modify version info')

    @property
    def patch(self):
        raise AttributeError('Cannot modify version info')

    @property
    def prerelease(self):
        raise AttributeError('Cannot modify version info')

    @property
    def build(self):
        raise AttributeError('Cannot modify version info')

def createparser():
    import argparse
    return argparse.ArgumentParser(description='pysemver')

def main():
    parser = createparser()
    args = parser.parse_args()
    print('pysemver')

def process():
    pass

def replace(version, **kwargs):
    return VersionInfo(version.major, version.minor, version.patch, version.prerelease, version.build).replace(**kwargs)
